        public static VentState VentAt(float time, Vec2 vent)
        {
            float phase = (time + vent.X * 0.125f) % 4f;
            return phase < 2f ? VentState.Quiet : phase < 3f ? VentState.Warning : VentState.Blowing;
        }

        public static Aabb JetBox(Vec2 feet) => new Aabb(new Vec2(feet.X, feet.Y + 1.5f), new Vec2(0.5f, 1.5f));

        public static readonly Vec2 TrapLift = new Vec2(125.5f, 2f);
        public static readonly Vec2 WellStop = new Vec2(122.5f, 20f);

        // The standalone pilot uses ordinary move, swing and lift inputs throughout.
        internal static PlayerInput RouteInput(World w, bool takeRecord = true)
        {
            Vec2 feet = w.Player.Body.Feet;
            float target = w.Level.Outlet.Value.X;
            bool up = false;
            foreach (Enemy e in w.Foes)
            {
                if (!(e is PumpMachine machine) || !e.Alive || e.Room != w.Room) continue;
                target = e.Home.X - 1f;
                if (machine.IsWarden && (machine.Beat == MachineBeat.Mark || machine.Beat == MachineBeat.Jet))
                {
                    target = machine.Lane == 1 ? e.Home.X - 2.9f : e.Home.X - 0.8f;
                }
                break;
            }
            if (takeRecord && w.Room == 3 && !w.GaugeFound && w.Foes.TrueForAll(e => e.Room != 3 || !e.Alive))
                target = 107.5f;
            if (w.Room == 4)
            {
                target = w.GaugeFound ? TrapLift.X : w.Level.Record.Value.X;
                up = w.GaugeFound && System.MathF.Abs(feet.X - target) < 0.5f;
            }
            if (w.Warden != null && !w.Warden.Alive && !w.PumpKey) target = w.Warden.Home.X;
            float move = System.MathF.Abs(target - feet.X) < 0.12f ? 0 : Mathx.Sign(target - feet.X);
            foreach (Vec2 vent in w.Level.Vents)
                if (System.MathF.Abs(feet.Y - vent.Y) < 2 && feet.X < vent.X - 1f && feet.X > vent.X - 3f &&
                    VentAt(w.Time, vent) != VentState.Quiet) move = 0;
            if (!w.GrateOpen && feet.X >= w.Level.Lever.X - 1.05f) move = 0;
            bool hop = !takeRecord && w.Room == 3 && feet.X >= 104.7f && feet.X < 108f;
            return new PlayerInput { JumpPressed = hop && w.Player.Body.Grounded, JumpHeld = hop, MoveX = move, Up = up, AttackPressed = feet.X > 64f };
        }
